const row = (value: unknown): value is Row => value !== null && typeof value === "object" && !Array.isArray(value);
const exact = (value: unknown, keys: string[]): value is Row => row(value) && Object.keys(value).length === keys.length && keys.every(key => Object.hasOwn(value, key));
