  if (Array.isArray(b)) return Array.isArray(a) && a.length === b.length && b.length <= 128 && b.every((item, index) => samePropertyValue(a[index], item, depth + 1));
  return row(b) && exact(a, Object.keys(b)) && Object.keys(b).every(key => samePropertyValue(a[key], b[key], depth + 1));
